type Position = { index: number; line: number; column: number };

type TextNode = { type: "text"; value: string };
type InterpolationNode = { type: "interpolation"; path: string; escaped: boolean; position: Position };
type BlockNode = {
  type: "block";
  kind: "if" | "each";
  path: string;
  body: Node[];
  otherwise: Node[] | null;
  position: Position;
};
type Node = TextNode | InterpolationNode | BlockNode;
type OpenBlock = { node: BlockNode; target: Node[]; elseSeen: boolean };

const scalarText = (value: unknown, position: Position): string => {
  if (value === null || value === undefined) return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
    return String(value);
  }
  throw syntaxError(`Cannot render ${typeof value} as scalar text`, position);
};

const escapeHtml = (value: string): string => value.replace(/[&<>"']/g, (character) => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
})[character] as string);

const syntaxError = (message: string, position: Position): Error =>
  new Error(`${message} at line ${position.line}, column ${position.column}`);

const positionAt = (source: string, index: number): Position => {
  let line = 1;
  let column = 1;
  for (let cursor = 0; cursor < index; cursor += 1) {
    if (source[cursor] === "\n") {
      line += 1;
      column = 1;
    } else {
      column += 1;
    }
  }
  return { index, line, column };
};

const validatePath = (path: string, position: Position): void => {
  if (!/^(?:this|@index|[A-Za-z_$][\w$]*)(?:\.[A-Za-z_$][\w$]*)*$/.test(path)) {
    throw syntaxError(`Invalid path "${path}"`, position);
  }
};

const parse = (template: string): Node[] => {
  const root: Node[] = [];
  const stack: OpenBlock[] = [];
  let target = root;
  let cursor = 0;

  const appendText = (value: string): void => {
    if (value) target.push({ type: "text", value });
  };

  while (cursor < template.length) {
    const opening = template.indexOf("{{", cursor);
    if (opening === -1) {
      appendText(template.slice(cursor));
      break;
    }
    appendText(template.slice(cursor, opening));
    const triple = template.startsWith("{{{", opening);
    const closeMarker = triple ? "}}}" : "}}";
    const contentStart = opening + (triple ? 3 : 2);
    const closing = template.indexOf(closeMarker, contentStart);
    const position = positionAt(template, opening);
    if (closing === -1) throw syntaxError("Unclosed tag", position);
    const content = template.slice(contentStart, closing).trim();
    cursor = closing + closeMarker.length;

    if (triple) {
      validatePath(content, position);
      target.push({ type: "interpolation", path: content, escaped: false, position });
      continue;
    }
    if (content.startsWith("!")) continue;
    if (content === "else") {
      const open = stack.at(-1);
      if (!open) throw syntaxError("Else outside a block", position);
      if (open.elseSeen) throw syntaxError("Duplicate else", position);
      open.elseSeen = true;
      open.node.otherwise = [];
      target = open.node.otherwise;
      continue;
    }
    if (content.startsWith("#")) {
      const match = /^#(if|each)\s+(.+)$/.exec(content);
      if (!match) throw syntaxError(`Unknown or malformed block "${content}"`, position);
      const [, kind, path] = match;
      validatePath(path, position);
      const node: BlockNode = { type: "block", kind: kind as BlockNode["kind"], path, body: [], otherwise: null, position };
      target.push(node);
      stack.push({ node, target, elseSeen: false });
      target = node.body;
      continue;
    }
    if (content.startsWith("/")) {
      const kind = content.slice(1).trim();
      const open = stack.at(-1);
      if (!open) throw syntaxError(`Close tag "${kind}" without an open block`, position);
      if (kind !== open.node.kind) throw syntaxError(`Mismatched close tag "${kind}", expected "${open.node.kind}"`, position);
      stack.pop();
      target = open.target;
      continue;
    }
    validatePath(content, position);
    target.push({ type: "interpolation", path: content, escaped: true, position });
  }
  const unclosed = stack.at(-1);
  if (unclosed) throw syntaxError(`Unclosed block "${unclosed.node.kind}"`, unclosed.node.position);
  return root;
};

type Context = { root: unknown; current: unknown; index: number | null };

const getProperty = (value: unknown, key: string): unknown => {
  if (value !== null && (typeof value === "object" || typeof value === "function")) return (value as Record<string, unknown>)[key];
  return undefined;
};

const resolve = (path: string, context: Context): unknown => {
  if (path === "this") return context.current;
  if (path === "@index") return context.index;
  const parts = path.split(".");
  let value = getProperty(context.current, parts[0]);
  if (value === undefined) value = getProperty(context.root, parts[0]);
  for (let index = 1; index < parts.length; index += 1) value = getProperty(value, parts[index]);
  return value;
};

const isTruthy = (value: unknown): boolean => {
  if (Array.isArray(value)) return value.length > 0;
  return Boolean(value);
};

const renderNodes = (nodes: Node[], context: Context): string => nodes.map((node) => {
  if (node.type === "text") return node.value;
  if (node.type === "interpolation") {
    const value = scalarText(resolve(node.path, context), node.position);
    return node.escaped ? escapeHtml(value) : value;
  }
  const value = resolve(node.path, context);
  if (node.kind === "if") return renderNodes(isTruthy(value) ? node.body : (node.otherwise ?? []), context);
  if (!Array.isArray(value)) return renderNodes(node.otherwise ?? [], context);
  if (value.length === 0) return renderNodes(node.otherwise ?? [], context);
  return value.map((item, index) => renderNodes(node.body, { root: context.root, current: item, index })).join("");
}).join("");

/** Render a Mini Template string with data from a root object or array. */
export const render = (template: string, data: unknown): string =>
  renderNodes(parse(template), { root: data, current: data, index: null });
import { render } from "./engine.ts";

const [templateFile, dataFile] = Bun.argv.slice(2);

if (!templateFile || !dataFile || Bun.argv.slice(2).length !== 2) {
  console.error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  process.exit(1);
}

try {
  const [template, json] = await Promise.all([Bun.file(templateFile).text(), Bun.file(dataFile).text()]);
  process.stdout.write(render(template, JSON.parse(json)));
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
import { expect, test } from "bun:test";
import { render } from "../src/engine.ts";

test("interpolates escaped and raw scalar values", () => {
  expect(render("{{value}} {{{value}}}", { value: "<a&\"'>" })).toBe("&lt;a&amp;&quot;&#39;&gt; <a&\"'>");
  expect(render("x{{missing}}y", {})).toBe("xy");
});

test("handles comments, conditions, and falsey empty arrays", () => {
  expect(render("a{{! ignored }}b{{#if items}}yes{{else}}no{{/if}}", { items: [] })).toBe("abno");
  expect(render("{{#if value}}yes{{else}}no{{/if}}", { value: 0 })).toBe("no");
});

test("renders nested loops with root fallback", () => {
  const template = "{{#each groups}}{{title}}:{{#each this}}[{{@index}}={{this}}/{{title}}]{{/each}};{{/each}}";
  expect(render(template, { title: "root", groups: [["a", "b"], ["c"]] })).toBe("root:[0=a/root][1=b/root];root:[0=c/root];");
});

test("renders each else and rejects structural and non-scalar values", () => {
  expect(render("{{#each values}}x{{else}}empty{{/each}}", { values: [] })).toBe("empty");
  expect(() => render("{{#if x}}a{{/each}}", { x: true })).toThrow(/line 1, column/);
  expect(() => render("{{value}}", { value: {} })).toThrow(/Cannot render object/);
});
